INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q01', 'shared-gk-bank', 'Indian Polity', 0, 0, 'Which Article of the Indian Constitution abolishes untouchability?', 'Article 17 of the Indian Constitution abolishes "untouchability" in any form and forbids its practice, making it a punishable offence under law — it falls under the Fundamental Rights (Right against Exploitation).', '2026-11-12T13:39:01.273Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q02', 'shared-gk-bank', 'Indian Polity', 0, 1, 'How many Fundamental Duties are listed in the Indian Constitution, and which Article covers them?', 'There are 11 Fundamental Duties, listed under Article 51A in Part IVA of the Constitution — added by the 42nd Amendment (1976) and later expanded by the 86th Amendment (2002), which added the duty regarding education for children aged 6-14.', '2026-11-12T13:39:01.273Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q03', 'shared-gk-bank', 'Indian Polity', 0, 2, 'What is the minimum age to become a member of the Lok Sabha?', 'The minimum age to contest and become a member of the Lok Sabha is 25 years, as prescribed under Article 84 of the Constitution.', '2026-11-12T13:39:01.273Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q04', 'shared-gk-bank', 'Indian Polity', 0, 3, 'Who appoints the Chief Election Commissioner of India?', 'The Chief Election Commissioner is appointed by the President of India, under Article 324 of the Constitution, which establishes the Election Commission.', '2026-11-12T13:39:01.273Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q05', 'shared-gk-bank', 'Indian Polity', 0, 4, 'What is the significance of Article 370, and what happened to it in 2019?', 'Article 370 granted special autonomous status to Jammu & Kashmir. On August 5, 2019, the Indian government revoked its special status via a Presidential Order and reorganized the state into two Union Territories — Jammu & Kashmir, and Ladakh.', '2026-11-12T13:39:01.273Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q06', 'shared-gk-bank', 'Geography', 1, 5, 'Which is the longest river in India, and where does it originate?', 'The Ganga is the longest river in India, originating from the Gangotri Glacier in Uttarakhand, flowing through the Gangetic Plains before emptying into the Bay of Bengal.', '2026-11-12T13:39:01.273Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q07', 'shared-gk-bank', 'Geography', 1, 6, 'Which state in India has the longest coastline?', 'Gujarat has the longest coastline among Indian states, at approximately 1,600 km, followed by Andhra Pradesh and Tamil Nadu.', '2026-11-12T13:39:01.273Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q08', 'shared-gk-bank', 'Geography', 1, 7, 'What is the "Tropic of Cancer" and which Indian states does it pass through?', 'The Tropic of Cancer is the latitude line at approximately 23.5° N, marking the northernmost point where the sun can appear directly overhead. In India, it passes through 8 states: Gujarat, Rajasthan, Madhya Pradesh, Chhattisgarh, Jharkhand, West Bengal, Tripura, and Mizoram.', '2026-11-12T13:39:01.273Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q09', 'shared-gk-bank', 'Geography', 1, 8, 'Which is the highest peak in India, and in which mountain range is it located?', 'Kangchenjunga, at 8,586 metres, is the highest peak located entirely within India (in Sikkim), part of the Himalayan range — it is the third-highest peak in the world.', '2026-11-12T13:39:01.273Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q10', 'shared-gk-bank', 'History', 2, 9, 'Who founded the Indian National Congress, and in which year?', 'The Indian National Congress was founded in 1885 by Allan Octavian Hume, a retired British civil servant, with its first session held in Bombay under the presidency of Womesh Chandra Bonnerjee.', '2026-11-12T13:39:01.273Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q11', 'shared-gk-bank', 'History', 2, 10, 'What was the significance of the Quit India Movement, and when was it launched?', 'The Quit India Movement was launched by Mahatma Gandhi on August 8, 1942, demanding an end to British rule in India — it was a mass civil disobedience movement under the slogan "Do or Die," marking one of the most significant movements of the independence struggle.', '2026-11-12T13:39:01.273Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q12', 'shared-gk-bank', 'History', 2, 11, 'Who was the first Governor-General of independent India?', 'Lord Mountbatten served as the first Governor-General of independent India from August 1947 to June 1948, after which C. Rajagopalachari became the first Indian to hold the post.', '2026-11-12T13:39:01.273Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q13', 'shared-gk-bank', 'Economy', 3, 12, 'What does "GDP" stand for, and what does it measure?', 'GDP stands for Gross Domestic Product — it measures the total monetary value of all finished goods and services produced within a country''s borders in a specific time period, serving as a key indicator of economic health.', '2026-11-12T13:39:01.273Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q14', 'shared-gk-bank', 'Economy', 3, 13, 'Which organization regulates India''s monetary policy, and what is its primary tool for controlling inflation?', 'The Reserve Bank of India (RBI) regulates monetary policy. Its primary tool for controlling inflation is the repo rate — the rate at which RBI lends to commercial banks; raising it makes borrowing costlier, which helps cool inflation.', '2026-11-12T13:39:01.273Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gk-q15', 'shared-gk-bank', 'Current Affairs & General Knowledge', 4, 14, 'What is the full form of "UPI", and what is its primary function in India?', 'UPI stands for Unified Payments Interface — developed by the National Payments Corporation of India (NPCI), it enables instant, real-time bank-to-bank money transfers through a mobile application, using a single app and identifier (like a VPA) instead of account details.', '2026-11-12T13:39:01.273Z');
INSERT INTO question_sets (id, owner_user_id, title, track, visibility, created_at, approved_at, approved_by) VALUES ('police-exam-bank', NULL, 'Police & Law Awareness', 'police', 'shared', '2026-11-12T13:39:01.273Z', '2026-11-12T13:39:01.273Z', NULL);
INSERT INTO question_set_categories (set_id, category_id) VALUES ('police-exam-bank', 'police-exam');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q01', 'police-exam-bank', 'Police Organization & Structure', 0, 0, 'What is the full form of "IPS", and what is its role?', 'IPS stands for Indian Police Service — one of the three All India Services (along with IAS and IFoS). IPS officers hold senior leadership and supervisory roles in state police forces and central police organizations, responsible for maintaining law and order, crime investigation oversight, and policy implementation.', '2026-11-12T13:39:01.273Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q02', 'police-exam-bank', 'Police Organization & Structure', 0, 1, 'What is the full form of "CRPF", and what is its primary role?', 'CRPF stands for Central Reserve Police Force — India''s largest central armed police force, primarily responsible for internal security duties including counter-insurgency, anti-terrorism operations, and law-and-order support to state police during elections and major public events.', '2026-11-12T13:39:01.273Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q03', 'police-exam-bank', 'Police Organization & Structure', 0, 2, 'What is the difference between the roles of a Station House Officer (SHO) and a Superintendent of Police (SP)?', 'An SHO is the officer-in-charge of a single police station, responsible for day-to-day law and order, registering FIRs, and local investigations within that station''s jurisdiction. An SP is a senior officer (typically an IPS rank) who heads police administration for an entire district, overseeing multiple police stations and overall district-level law and order, crime strategy, and personnel management.', '2026-11-12T13:39:01.273Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q04', 'police-exam-bank', 'Police Organization & Structure', 0, 3, 'What does "FIR" stand for, and who can file one?', 'FIR stands for First Information Report — a written document prepared by police when they receive information about the commission of a cognizable offence. Any person who has knowledge of the commission of a cognizable offence can file an FIR, including the victim, a witness, or someone acting on the victim''s behalf.', '2026-11-12T13:39:01.273Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q05', 'police-exam-bank', 'Police Organization & Structure', 0, 4, 'What is the role of the National Crime Records Bureau (NCRB)?', 'The NCRB is responsible for collecting, compiling, and analyzing crime data from across India, publishing the annual "Crime in India" report, and maintaining national databases on crime and criminals (such as fingerprint records) to support policing and policy decisions.', '2026-11-12T13:39:01.273Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q06', 'police-exam-bank', 'Law & Legal Awareness', 1, 5, 'What is the difference between a cognizable and a non-cognizable offence?', 'In a cognizable offence, police can arrest the accused without a warrant and begin investigation without prior court permission (e.g., murder, robbery) — these are typically serious crimes. In a non-cognizable offence, police cannot arrest without a warrant and need court permission to investigate (e.g., simple hurt, public nuisance) — these are typically less severe.', '2026-11-12T13:39:01.273Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q07', 'police-exam-bank', 'Law & Legal Awareness', 1, 6, 'What does "IPC" stand for, and what has replaced it?', 'IPC stands for the Indian Penal Code, India''s main criminal code since 1860, defining various offences and their punishments. It has been replaced by the Bharatiya Nyaya Sanhita (BNS), 2023, which came into effect in 2024 as part of a broader overhaul of India''s criminal laws.', '2026-11-12T13:39:01.273Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q08', 'police-exam-bank', 'Law & Legal Awareness', 1, 7, 'What is "anticipatory bail", and under which provision can it be sought?', 'Anticipatory bail is bail granted to a person in anticipation of arrest, before they are actually arrested, when they have reasonable grounds to believe they may be arrested for a non-bailable offence. It can be sought under Section 482 of the Bharatiya Nagarik Suraksha Sanhita (BNSS), 2023 (previously Section 438 of the CrPC).', '2026-11-12T13:39:01.273Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q09', 'police-exam-bank', 'Law & Legal Awareness', 1, 8, 'What is the purpose of a "charge sheet" in a criminal investigation?', 'A charge sheet (also called a "final report") is a formal document prepared by the investigating police officer after completing investigation, listing the accused, the evidence collected, and the specific charges/sections of law applicable — it is filed in court to begin the trial process.', '2026-11-12T13:39:01.273Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q10', 'police-exam-bank', 'Law & Legal Awareness', 1, 9, 'What is the legal principle behind "presumption of innocence"?', 'The presumption of innocence is a fundamental legal principle stating that an accused person is considered innocent until proven guilty beyond reasonable doubt in a court of law — the burden of proving guilt rests on the prosecution, not on the accused to prove their innocence.', '2026-11-12T13:39:01.273Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q11', 'police-exam-bank', 'Current Affairs & Law Updates', 2, 10, 'What are the three new criminal laws that replaced the IPC, CrPC, and Indian Evidence Act in India, and when did they take effect?', 'The Bharatiya Nyaya Sanhita (BNS) replaced the IPC, the Bharatiya Nagarik Suraksha Sanhita (BNSS) replaced the CrPC, and the Bharatiya Sakshya Adhiniyam (BSA) replaced the Indian Evidence Act. All three came into effect on July 1, 2024.', '2026-11-12T13:39:01.273Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q12', 'police-exam-bank', 'Current Affairs & Law Updates', 2, 11, 'What is the role of the National Investigation Agency (NIA)?', 'The NIA is India''s federal counter-terrorism law enforcement agency, established in 2009 after the Mumbai terror attacks. It investigates and prosecutes offences related to terrorism, insurgency, and other matters affecting national security, operating across state boundaries without needing individual state permissions.', '2026-11-12T13:39:01.273Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q13', 'police-exam-bank', 'Current Affairs & Law Updates', 2, 12, 'What is "community policing", and what is its goal?', 'Community policing is a strategy where police actively collaborate with local community members to identify and solve public safety problems, rather than relying only on reactive law enforcement. Its goal is to build trust, improve crime prevention through local intelligence, and make policing more responsive to community needs.', '2026-11-12T13:39:01.273Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q14', 'police-exam-bank', 'Current Affairs & Law Updates', 2, 13, 'What does "cyber forensics" involve in a police investigation?', 'Cyber forensics involves collecting, preserving, and analyzing digital evidence (from computers, mobile phones, servers, networks) in a legally admissible manner to investigate crimes — including financial fraud, hacking, cyberstalking, and crimes where digital devices hold key evidence.', '2026-11-12T13:39:01.273Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('police-q15', 'police-exam-bank', 'Current Affairs & Law Updates', 2, 14, 'What is the purpose of the Protection of Children from Sexual Offences (POCSO) Act, 2012?', 'The POCSO Act provides a comprehensive legal framework to protect children from sexual abuse and exploitation, defining specific offences against children, prescribing stringent punishments, and establishing child-friendly procedures for reporting, recording evidence, investigation, and trial.', '2026-11-12T13:39:01.273Z');
